/**
 * auth/create-org.ts — createOrgWithOwner (self-serve signup).
 *
 * Creates a brand-new tenant: an org + its OWNER app_user + membership(owner) +
 * auth_credential (argon2id hash) + terms/privacy acceptance records, ATOMICALLY
 * in one transaction. This is the ONLY self-serve path that mints an org — every
 * other org INSERT is the demo seeder.
 *
 * ── SECURITY (tenant creation is the most sensitive operation in the app) ──────
 *   - UNAUTHENTICATED by nature (signup has no session). No session, no org_id
 *     ever comes from the caller — the new org_id is generated by the INSERT.
 *   - The org INSERT requires platform-admin RLS context (org_insert policy).
 *     We set app.platform_admin='on' to insert the org, then set
 *     app.current_org_id to the NEW org so the owner/membership/credential/
 *     acceptance inserts pass their org-scoped RLS — all inside ONE
 *     db.transaction so a mid-failure creates NOTHING (no orphan org, no
 *     half-provisioned tenant). Composed GUCs are the deliberate exception to
 *     the withOrgContext/withPlatformAdminContext wrappers, justified by the
 *     atomicity requirement and documented here.
 *   - SLUG is derived from the org name (pure deriveSlugCandidate) and is the
 *     tenant URL key. On a unique-violation (slug raced) the whole tx rolls back
 *     and the next candidate is tried in a fresh tx — the org INSERT is the
 *     first write, so a rollback leaves zero rows. Reserved route names are
 *     skipped by the pure helper.
 *   - CLICKWRAP: acceptedTerms must be true (validation) — you cannot sign up
 *     without agreeing. The terms_acceptance rows are the durable proof;
 *     GRACEFUL ABSENCE (migration 0049 unapplied) skips the write but STILL
 *     requires the checkbox.
 *   - ANTI-ABUSE: a honeypot field (must be empty). Edge rate-limiting + CAPTCHA
 *     are a launch predecessor before this route is internet-exposed
 *     ([VERIFY-SIGNUP-SEC-1]) — mirrors the public booking page's posture.
 *   - The password is hashed ONCE (argon2id, ~19MB) before the retry loop.
 *
 * NO money, NO card/bank data. NO FAA determination.
 */

import { z } from 'zod';
import { sql } from 'drizzle-orm';
import { org, appUser, membership, authCredential } from '@aeroops/db';
import type { AnyDb } from '@aeroops/db';
import {
  deriveSlugBase,
  deriveSlugCandidate,
  LEGAL_DOCUMENT_VERSION,
} from '@aeroops/core';
import { getDb } from '../db.js';
import { hashPassword } from './hash.js';
import { isUniqueViolation } from '../dispatch/internal.js';
import { ValidationError } from '../scheduling/internal.js';

/** Max slug candidates to try before giving up (base + 24 numeric suffixes). */
const MAX_SLUG_ATTEMPTS = 25;

const createOrgInputSchema = z.object({
  orgName: z.string().trim().min(2, { message: 'Enter your operation name' }).max(120),
  ownerFullName: z.string().trim().min(1, { message: 'Enter your name' }).max(120),
  email: z.string().trim().toLowerCase().email({ message: 'Enter a valid email address' }).max(254),
  password: z
    .string()
    .min(10, { message: 'Use at least 10 characters' })
    .max(200, { message: 'Password is too long' }),
  acceptedTerms: z.literal(true, { message: 'You must accept the Terms and Privacy Policy' }),
  /** Honeypot — bots fill it, humans leave it empty. */
  website: z.string().max(0).optional(),
});

export type CreateOrgWithOwnerInput = z.infer<typeof createOrgInputSchema>;

export type CreateOrgWithOwnerResult =
  | { ok: true; slug: string; email: string }
  | { ok: false; reason: 'invalid_name' }
  | { ok: false; reason: 'slug_unavailable' };

async function _createOrgWithOwnerImpl(
  db: AnyDb,
  rawInput: unknown,
  acceptedIp: string | null,
): Promise<CreateOrgWithOwnerResult> {
  // 1. Validate. A bad honeypot (non-empty) fails max(0) here → generic invalid.
  const parsed = createOrgInputSchema.safeParse(rawInput);
  if (!parsed.success) {
    const first = parsed.error.issues[0];
    throw new ValidationError(`[signup] ${first?.message ?? 'invalid input'}`);
  }
  const { orgName, ownerFullName, email, password } = parsed.data;

  // 2. Derive a slug base from the org name. No usable slug (all punctuation,
  //    too short, reserved) → ask for a different name.
  const slugBase = deriveSlugBase(orgName);
  if (!slugBase) {
    return { ok: false, reason: 'invalid_name' } as const;
  }

  // 3. Hash the password ONCE (argon2id is deliberately expensive).
  const passwordHash = await hashPassword(password);

  // 4. Try slug candidates until one inserts cleanly. Each attempt is a fully
  //    atomic transaction: org + owner + membership + credential + acceptance
  //    all commit together, or (on a slug race) all roll back and we try the
  //    next candidate. The org INSERT is the FIRST write, so a rollback here
  //    leaves NO orphan rows.
  for (let attempt = 0; attempt < MAX_SLUG_ATTEMPTS; attempt++) {
    const candidate = deriveSlugCandidate(slugBase, attempt);
    if (!candidate) continue;

    try {
      const created = await db.transaction(async (tx) => {
        const t = tx as AnyDb;

        // Control-plane: platform-admin GUC to satisfy org_insert RLS.
        await t.execute(sql`select set_config('app.platform_admin', 'on', true)`);
        const [orgRow] = await t
          .insert(org)
          .values({ name: orgName, slug: candidate, status: 'active' })
          .returning();
        if (!orgRow) throw new Error('[signup] org insert returned no row');

        // Switch to the NEW org's tenant context for the owner-side inserts.
        await t.execute(sql`select set_config('app.current_org_id', ${orgRow.id}, true)`);
        await t.execute(sql`select set_config('app.platform_admin', '', true)`);

        const [ownerRow] = await t
          .insert(appUser)
          .values({ orgId: orgRow.id, email, fullName: ownerFullName })
          .returning();
        if (!ownerRow) throw new Error('[signup] owner insert returned no row');

        await t.insert(membership).values({ orgId: orgRow.id, userId: ownerRow.id, role: 'owner' });
        await t.insert(authCredential).values({ orgId: orgRow.id, userId: ownerRow.id, passwordHash });

        // Legal record — append-only, graceful-absent (migration 0049 staged).
        if (await termsAcceptanceTableExists(t)) {
          for (const document of ['terms', 'privacy'] as const) {
            await t.execute(sql`
              INSERT INTO "terms_acceptance"
                ("org_id", "user_id", "document", "version", "accepted_ip")
              VALUES (${orgRow.id}::uuid, ${ownerRow.id}::uuid, ${document},
                      ${LEGAL_DOCUMENT_VERSION}, ${acceptedIp})
            `);
          }
        }

        return { slug: orgRow.slug };
      });

      return { ok: true, slug: created.slug, email } as const;
    } catch (err) {
      // Slug raced another signup → roll forward to the next candidate.
      if (isUniqueViolation(err)) continue;
      throw err;
    }
  }

  return { ok: false, reason: 'slug_unavailable' } as const;
}

/** Catalog-only probe — true iff migration 0049's terms_acceptance table exists. */
async function termsAcceptanceTableExists(tx: AnyDb): Promise<boolean> {
  const res = await tx.execute(sql`SELECT to_regclass('terms_acceptance')::text AS reg`);
  const rows = (Array.isArray(res) ? res : ((res as { rows?: unknown[] }).rows ?? [])) as Array<{
    reg: string | null;
  }>;
  return Boolean(rows[0]?.reg);
}

export async function createOrgWithOwner(
  input: unknown,
  acceptedIp?: string | null,
): Promise<CreateOrgWithOwnerResult> {
  const db = await getDb();
  return _createOrgWithOwnerImpl(db, input, acceptedIp ?? null);
}

export async function createOrgWithOwnerWithDb(
  db: AnyDb,
  input: unknown,
  acceptedIp?: string | null,
): Promise<CreateOrgWithOwnerResult> {
  return _createOrgWithOwnerImpl(db, input, acceptedIp ?? null);
}
